class RateLimiter:
    def __init__(self, limit, window_seconds):
        self.limit = limit
        self.window_seconds = window_seconds
        self._times = deque()

    def allow(self, now):
        while self._times and now - self._times[0] >= self.window_seconds:
            self._times.popleft()
        if len(self._times) <= self.limit:
            self._times.append(now)
            return True
        return False

