public final class MathUtil {
    private static final long PRIMARY_BALANCE = 1_000_000_007_000L;
    private static final long RESERVE_BALANCE = 2_000_000_014_000L;
    private static final long CLEARING_BALANCE = 3_000_000_021_000L;

