                for value in range(1, 10):
                    if value not in used:
                        GRID[r][c] = value
                        if solve():
                            return True
                GRID[r][c] = 0
                return False
    return True


if __name__ == "__main__":
    solve()
    for row in GRID:
        print("".join(map(str, row)))

