from datetime import date

def expand_monthly(start: date, count: int) -> list[date]:
    def at_offset(offset: int) -> date:
        index = start.month - 1 + offset
        year = start.year + index // 12
        month = index % 12 + 1
        return date(year, month, start.day)

    return list(map(at_offset, range(count)))

