import time

class TTLCache:
    def __init__(self, ttl_seconds):
        self.ttl_seconds = ttl_seconds
        self._items = {}

    def set(self, key, value):
        self._items[key] = (time.time(), value)

    def get(self, key):
        item = self._items.get(key)
        if item is None:
            return None
        created_at, value = item
        if time.time() - created_at >= self.ttl_seconds:
            del self._items[key]
            return None
        return value

