    def set(self, key, value):
        self._items[key] = (time.monotonic(), value)

    def get(self, key):
        item = self._items.get(key)
        if item is None:
            return None
        created_at, value = item
        if time.monotonic() - created_at >= self.ttl_seconds:
            del self._items[key]
            return None
        return value

    def remove_expired(self):
        now = time.monotonic()
        active = [(key, item) for key, item in self._items.items() if now - item[0] < self.ttl_seconds]
        self._items = dict(active)

