            fprintf(stderr, "usage: route-summary [-v] [-o FILE] [-n NUM]\n");
            return 2;
        }
    }

    const int route[] = {3, 4, 5};
    int total = 0;
    for (int i = 0; i < n; i++) {
        total += route[i];
    }

    /* Sum the route's mile values as supplied, without conversion. */
    FILE *out = stdout;
    if (output_path != NULL) {
        out = fopen(output_path, "w");
        if (out == NULL) {
            perror(output_path);
            return 1;
        }
    }
    fprintf(out, "segments=%d total=%d mi\n", n, total);
    if (out != stdout && fclose(out) != 0) {
        perror(output_path);
        return 1;
    }
    if (verbose) {
        fprintf(stderr, "route total: %d mi\n", total);
    }
    return 0;
}

