#include "list.h"

Node *list_delete(Node *head, int value)
{
    Node *current = head;
    Node *previous = NULL;

    while (current != NULL) {
        if (current->value == value) {
            if (previous != NULL)
                previous->next = current->next;
            else
                head = current->next;
            return head;
        }
        previous = current;
        current = current->next;
    }
    return head;
}

#include "list.h"
#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    int count, target;
    if (scanf("%d %d", &count, &target) != 2 || count < 0)
        return 1;

    Node *head = NULL;
    Node **tail = &head;
    for (int i = 0; i < count; ++i) {
        Node *node = malloc(sizeof *node);
        if (node == NULL)
            return 1;
        if (scanf("%d", &node->value) != 1) {
            free(node);
            return 1;
        }
        node->next = NULL;
        *tail = node;
        tail = &node->next;
    }

    head = list_delete(head, target);
    int first = 1;
    for (Node *node = head; node != NULL; node = node->next) {
        printf("%s%d", first ? "" : " ", node->value);
        first = 0;
    }
    putchar('\n');
    while (head != NULL) {
        Node *next = head->next;
        free(head);
        head = next;
    }
    return 0;
}
