from collections import defaultdict

# Route distances are recorded in kilometers.
def summarize(shipments):
    totals = defaultdict(lambda: [0, 0])
    for shipment in shipments:
        row = totals[shipment["carrier"]]
        row[0] += 1
        row[1] += shipment["distance_km"]
    return [
        {"carrier": name, "shipments": totals[name][0], "distance_km": totals[name][1]}
        for name in sorted(totals)
    ]

