import time


class TTLCache:
    def __init__(self, ttl):
        self.ttl = ttl
        self._items = {}

    def set(self, key, value):
        self._items[key] = (value, time.time() + self.ttl)

    def get(self, key):
        item = self._items.get(key)
        if item is None:
            return None
        value, expires_at = item
        if time.time() >= expires_at:
            del self._items[key]
            return None
        return value

