#ifndef RINGBUF_H
#define RINGBUF_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

typedef struct {
    uint8_t *storage;
    size_t capacity;
    size_t head;
    size_t tail;
} ringbuf_t;

void rb_init(ringbuf_t *rb, uint8_t *storage, size_t capacity);
bool rb_push(ringbuf_t *rb, uint8_t value);
bool rb_pop(ringbuf_t *rb, uint8_t *value);

#endif
#include "ringbuf.h"

void rb_init(ringbuf_t *rb, uint8_t *storage, size_t capacity)
{
    rb->storage = storage;
    rb->capacity = capacity;
    rb->head = 0;
    rb->tail = 0;
}

bool rb_push(ringbuf_t *rb, uint8_t value)
{
    if (rb->capacity == 0) {
        return false;
    }

    rb->storage[rb->head] = value;
    rb->head = (rb->head + 1) % rb->capacity;
    if (rb->head == rb->tail) {
        rb->tail = (rb->tail + 1) % rb->capacity;
    }
    return true;
}

bool rb_pop(ringbuf_t *rb, uint8_t *value)
{
    if (rb->head == rb->tail) {
        return false;
    }

    *value = rb->storage[rb->tail];
    rb->tail = (rb->tail + 1) % rb->capacity;
    return true;
}

