import argparse
import sqlite3
from pathlib import Path

DB_PATH = Path("data/ledger.db")
MIGRATIONS = [
    ("001_create_ledger", "CREATE TABLE IF NOT EXISTS ledger (id INTEGER PRIMARY KEY, amount_cents INTEGER NOT NULL);"),
    ("002_add_currency", "ALTER TABLE ledger ADD COLUMN currency TEXT NOT NULL DEFAULT 'USD';"),
]


def applied_migrations(connection):
    exists = connection.execute(
        "SELECT 1 FROM sqlite_master WHERE type = 'table' AND name = 'schema_migrations'"
    ).fetchone()
    if exists is None:
        return set()
    return {row[0] for row in connection.execute("SELECT name FROM schema_migrations")}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--database", default=str(DB_PATH))
    args = parser.parse_args()
    connection = sqlite3.connect(args.database)
    connection.execute(
        "CREATE TABLE IF NOT EXISTS schema_migrations (name TEXT PRIMARY KEY)"
    )
    applied = applied_migrations(connection)
    for name, sql in MIGRATIONS:
        if name in applied:
            continue
        connection.execute(sql)
        connection.execute(
            "INSERT INTO schema_migrations (name) VALUES (?)", (name,)
        )
    connection.commit()
    connection.close()


if __name__ == "__main__":
    main()

