import java.util.List;
import java.util.stream.Collectors;

public final class Flags {
    public record DriverRecord(String id, double bac, boolean flagged) {}

    private Flags() {}

    public static List<DriverRecord> flagOutsideRange(
            List<DriverRecord> drivers, double minimum, double maximum) {
        if (minimum > maximum) {
            throw new IllegalArgumentException("minimum exceeds maximum");
        }
        return drivers.stream()
                .map(driver -> new DriverRecord(
                        driver.id(),
                        driver.bac(),
                        driver.bac() < minimum || driver.bac() > maximum))
                .collect(Collectors.toList());
    }
}

