pub struct LatencyKeeper {
    capacity: usize,
    samples: Vec<u64>,
}

impl LatencyKeeper {
    pub fn new(capacity: usize) -> Self {
        Self {
            capacity,
            samples: Vec::new(),
        }
    }

    pub fn record(&mut self, latency_ms: u64) {
        self.samples.push(latency_ms);
        if self.samples.len() > self.capacity {
            self.samples.remove(0);
        }
    }

    pub fn samples(&self) -> &[u64] {
        &self.samples
    }
}

