from pathlib import Path
import sys


def differing_files(left_dir, right_dir):
    left = Path(left_dir)
    right = Path(right_dir)
    changed = []
    for path in left.rglob("*"):
        if path.is_file():
            other = right / path.relative_to(left)
            if other.exists() and path.read_bytes() != other.read_bytes():
                changed.append(path.relative_to(left).as_posix())
    return sorted(changed)


if __name__ == "__main__":
    if len(sys.argv) != 3:
        raise SystemExit("usage: diff_dirs.py LEFT RIGHT")
    for name in differing_files(sys.argv[1], sys.argv[2]):
        print(name)

