package pool

import "sync"

type Pool struct {
	workers int
}

func New(workers int) *Pool {
	if workers < 1 {
		workers = 1
	}
	return &Pool{workers: workers}
}

func (p *Pool) Run(jobs <-chan func()) {
	var wg sync.WaitGroup
	for i := 0; i < p.workers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for {
				job := <-jobs
				if job == nil {
					continue
				}
				job()
			}
		}()
	}
	wg.Wait()
}

