import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"sync"

	"example.com/poolrepo/internal/pool"
)

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	jobs := make(chan func(), 4)
	var mu sync.Mutex
	total := 0
	for scanner.Scan() {
		value, err := strconv.Atoi(scanner.Text())
		if err != nil {
			panic(err)
		}
		n := value
		jobs <- func() {
			mu.Lock()
			total += n
			mu.Unlock()
		}
	}
	close(jobs)
	pool.New(2).Run(jobs)
	fmt.Println(total)
}

