from pathlib import Path

binary = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}
unary = {ast.UAdd: operator.pos, ast.USub: operator.neg}
def calc(node):
    if isinstance(node, ast.Expression): return calc(node.body)
    if isinstance(node, ast.Constant) and type(node.value) in (int, float): return node.value
    if isinstance(node, ast.BinOp) and type(node.op) in binary: return binary[type(node.op)](calc(node.left), calc(node.right))
    if isinstance(node, ast.UnaryOp) and type(node.op) in unary: return unary[type(node.op)](calc(node.operand))
    raise ValueError("unsupported expression")
