import json
import pathlib
import sys


def counts(path):
    data = pathlib.Path(path).read_bytes()
    lines = data.count(b"\n")
    if data and not data.endswith(b"\n"):
        lines += 1
    return {"bytes": len(data), "words": len(data.split()), "lines": lines}


