    output = json.load(stream)
required = {"bytes", "words", "lines"}
if set(output) != required:
    raise SystemExit("output keys must be bytes, words, lines")
if output != counts(sys.argv[2]):
    raise SystemExit("output values do not match input")
print("output format and counts are valid")

