int main(int argc, char **argv) {
    FILE *fp;
    int c;
    long bytes = 0, words = 0, lines = 0;
    if (argc != 2 || (fp = fopen(argv[1], "rb")) == NULL) {
        fprintf(stderr, "usage: count FILE\n");
        return 1;
    }
    while ((c = fgetc(fp)) != EOF) {
        bytes++;
        if (c == ' ') words++;
        if (c == '\n') lines++;
    }
    fclose(fp);
    printf("bytes=%ld words=%ld lines=%ld\n", bytes, words, lines);
    return 0;
}

