export type Player = "R" | "Y";
export type Cell = Player | null;

export function hasWon(board: Cell[][], row: number, col: number, player: Player): boolean {
  const rowCells = board[row] ?? [];
  let run = 0;
  for (const cell of rowCells) {
    run = cell === player ? run + 1 : 0;
    if (run === 4) return true;
  }
  return false;
}
