I'll just use `getopt`; it handles option ordering and argument consumption, and the wrapper enforces the ticket's value rules. Its parser also handles clustered flags and missing option arguments consistently, while I reject duplicates and operands.
```bash
cat > src/main.c <<'EOF'
#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

/* Parse a decimal count from 1 through 99; return -1 on invalid input. */
static int number(const char *s) {
    char *end;
    long x;
    if (!*s || strspn(s, "0123456789") != strlen(s)) return -1;
    x = strtol(s, &end, 10);
    return *end || x < 1 || x > 99 ? -1 : (int)x;
}

int main(int argc, char **argv) {
    int c, v = 0, seen_o = 0, seen_n = 0, n = 1;
    const char *o = "-";
    opterr = 0;
    while ((c = getopt(argc, argv, "vo:n:")) != -1) {
        if (c == 'v' && !v) v = 1;
        else if (c == 'o' && !seen_o && *optarg && *optarg != '-') o = optarg, seen_o = 1;
        else if (c == 'n' && !seen_n && number(optarg) > 0) n = number(optarg), seen_n = 1;
        else return 2;
    }
    if (optind != argc) return 2;
    printf("verbose=%d output=%s count=%d\n", v, o, n);
    return 0;
}
EOF
