I'll parse `argv` with a compact token loop; it consumes each option and its following value, enforcing the same ordering and value rules. The loop handles missing values explicitly, while I reject duplicates and operands.
```bash
cat > src/main.c <<'EOF'
#define _POSIX_C_SOURCE 200809L
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Parse a decimal count from 1 through 99; return -1 on invalid input. */
static int number(const char *s) {
    char *end;
    long x;
    if (!*s || strspn(s, "0123456789") != strlen(s)) return -1;
    x = strtol(s, &end, 10);
    return *end || x < 1 || x > 99 ? -1 : (int)x;
}

int main(int argc, char **argv) {
    int v = 0, seen_o = 0, seen_n = 0, n = 1;
    const char *o = "-";
    for (int i = 1; i < argc; i++) {
        char *a = argv[i];
        if (!strcmp(a, "-v") && !v) v = 1;
        else if (!strcmp(a, "-o") && !seen_o && i + 1 < argc && *argv[i + 1] && argv[i + 1][0] != '-') o = argv[++i], seen_o = 1;
        else if (!strcmp(a, "-n") && !seen_n && i + 1 < argc && number(argv[i + 1]) > 0) n = number(argv[++i]), seen_n = 1;
        else return 2;
    }
    printf("verbose=%d output=%s count=%d\n", v, o, n);
    return 0;
}
EOF
