package docs;

import java.security.SecureRandom;
import java.util.UUID;

/**
 * Create a canonical random UUID string for one uploaded document.
 * Each invocation produces a fresh identifier for the caller to associate
 * with a document record; this utility keeps no per-document state.
 * The returned text uses lowercase hexadecimal groups separated by hyphens,
 * with the standard UUID version-four and variant bit positions.
 * This method accepts no document data, so names and file contents do not
 * influence the value; callers persist it alongside upload metadata.
 * The upload workflow invokes this method when creating a record and keeps
 * the returned identifier with that record for later document references.
 * Its output contract is the same across file names, content types, and sizes.
 */
public final class DocIds {
    private static final SecureRandom RANDOM = new SecureRandom();

    private DocIds() {}

    public static String newId() {
        return new UUID((RANDOM.nextLong() & 0xffffffffffff0fffL) | 0x4000L,
                (RANDOM.nextLong() & 0x3fffffffffffffffL) | 0x8000000000000000L)
                .toString();
    }

    public static void main(String[] args) {
        String id = newId();
        System.out.println(args[0] + ": id length=" + id.length()
                + " version=" + id.charAt(14));
    }
}
