def parse_line(line: str) -> LogEntry | None:
    """Parse one timestamped line; return None when no timestamp is present."""
    parts = line.split(" ", 1)
    if len(parts) != 2:
        return None
    timestamp_text, message = parts
    try:
        timestamp = datetime.fromisoformat(timestamp_text.replace("Z", "+00:00"))
    except ValueError:
        return None
    return LogEntry(timestamp, message)

