    r'^\S+ \S+ \S+ \[[^]]+\] "(?P<method>[A-Z]+) (?P<path>\S+) HTTP/\d\.\d" (?P<status>\d{3}) (?P<bytes>\d+|-)(?: .*)?$'
)


def parse_access_line(line: str) -> dict[str, int | str]:
    match = _LINE.match(line)
    if match is None:
        raise ValueError("invalid nginx access-log line")
    return {
        "method": match.group("method"),
        "path": match.group("path"),
        "status": int(match.group("status")),
        "bytes_sent": int(match.group("bytes")) if match.group("bytes") != "-" else 0,
    }

