import hashlib


def sha256_upload(upload, chunk_size=64 * 1024):
    """Return the SHA-256 hex digest of an upload, reading bounded chunks."""
    if chunk_size <= 0:
        raise ValueError("chunk_size must be positive")
    digest = hashlib.sha256()
    while True:
        chunk = upload.read(chunk_size)
        if not chunk:
            break
        digest.update(chunk)
    return digest.hexdigest()

