def build_weekly_summary(readings, site_ranges=None):
    """Count valid IgE readings by site using inclusive site ranges."""
    ranges = site_ranges or {}
    summary = {
        site: {"normal": 0, "out_of_range": 0}
        for site in ranges
    }
    for reading in readings:
        site = reading["site"]
        summary.setdefault(site, {"normal": 0, "out_of_range": 0})
        value = reading.get("ige")
        if value is None:
