    summary = {
        site: {"normal": 0, "out_of_range": 0}
        for site in ranges
    }
    for reading in readings:
        site = reading["site"]
        summary.setdefault(site, {"normal": 0, "out_of_range": 0})
        value = reading.get("ige")
        if value is None:
