pub fn parse_bits(input: &str) -> Result<u32, BitParseError> {
    if input.is_empty() {
        return Err(BitParseError::Empty);
    }
    let mut value = 0u32;
    for byte in input.bytes() {
        let bit = match byte {
            b'0' => 0,
            b'1' => 1,
            _ => return Err(BitParseError::InvalidDigit),
        };
        value = value
            .checked_mul(2)
            .and_then(|n| n.checked_add(bit))
            .ok_or(BitParseError::Overflow)?;
    }
    Ok(value)
}

