def remaining_vacation_days(
    annual_allowance: int,
    used_days: int,
    previous_unused: int,
    carryover_cap: int | None = None,
) -> int:
    """Return unused allowance with capped prior-year carry-over."""
    if carryover_cap is None:
        carryover_cap = int(os.getenv("VACATION_CARRYOVER_CAP", "0"))
    carried = min(max(previous_unused, 0), max(carryover_cap, 0))
