const defaultTCPTimeout = 2 * time.Second

func effectiveTimeout(timeout time.Duration) time.Duration {
	if timeout <= 0 {
		return defaultTCPTimeout
	}
	return timeout
}

func TCPReachable(address string, timeout time.Duration) bool {
	conn, err := net.DialTimeout("tcp", address, effectiveTimeout(timeout))
	if err != nil {
		return false
	}
	defer conn.Close()
	return true
}

