package limit

import (
	"math"
	"sync"
	"time"
)

type clientState struct {
	tokens float64
	at     time.Time
}

type Bucket struct {
	mu              sync.Mutex
	capacity        float64
	refillPerSecond float64
	clients         map[string]clientState
}

func NewBucket(capacity int, refillPerSecond float64) *Bucket {
	return &Bucket{
		capacity:        float64(capacity),
		refillPerSecond: refillPerSecond,
		clients:         make(map[string]clientState),
	}
}

func (b *Bucket) Allow(clientID string, now time.Time) bool {
	b.mu.Lock()
	defer b.mu.Unlock()

	state, ok := b.clients[clientID]
	if !ok {
		state = clientState{tokens: b.capacity, at: now}
	} else if elapsed := now.Sub(state.at).Seconds(); elapsed > 0 {
		state.tokens = math.Min(b.capacity, state.tokens+elapsed*b.refillPerSecond)
		state.at = now
	}

	if state.tokens < 1 {
		b.clients[clientID] = state
		return false
	}
	state.tokens--
	b.clients[clientID] = state
	return true
}

