)

func main() {
	f, err := os.Open("samples/co_readings.csv")
	if err != nil {
		panic(err)
	}
	defer f.Close()

	records, err := csv.NewReader(f).ReadAll()
	if err != nil {
		panic(err)
	}
	rows := make([]emissions.Reading, 0, len(records)-1)
	for _, record := range records[1:] {
		observedAt, err := time.Parse("2006-01-02", record[2])
		if err != nil {
			panic(err)
		}
		value, err := strconv.ParseFloat(record[3], 64)
		if err != nil {
			panic(err)
		}
		rows = append(rows, emissions.Reading{
			Site: record[0], VehicleID: record[1], ObservedAt: observedAt, COPercent: value,
		})
	}
	weekStart := time.Date(2025, 2, 3, 0, 0, 0, 0, time.UTC)
	for _, result := range emissions.BuildWeeklySummary(rows, weekStart) {
		fmt.Printf("%s normal=%d out_of_range=%d\n", result.Site, result.Normal, result.OutOfRange)
	}
}
