    """Encode a row as (pixel, run length) pairs."""
    runs = []
    current = pixels[0]
    count = 1
    for pixel in pixels[1:]:
        if pixel == current:
            count += 1
        else:
            runs.append((current, count))
            current = pixel
            count = 1
    runs.append((current, count))
    return runs


