        if (args.length != 2) {
            throw new IllegalArgumentException("Provide two decimal balances");
        }
        System.out.println("GCD(" + args[0] + ", " + args[1] + ") = "
                + gcd(new BigInteger(args[0]), new BigInteger(args[1])));
    }
