import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

public final class Scheduler {
    public static final class Booking {
        public final int start;
        public final int end;

        public Booking(int start, int end) {
            this.start = start;
            this.end = end;
        }
    }

    public static int maxNonOverlapping(List<Booking> bookings) {
        List<Booking> ordered = new ArrayList<>(bookings);
        ordered.sort(Comparator.comparingInt(b -> b.start));
        int count = 0;
        int lastEnd = Integer.MIN_VALUE;
        for (Booking booking : ordered) {
            if (booking.start >= lastEnd) {
                count++;
                lastEnd = booking.end;
            }
        }
        return count;
    }
}

