from functools import lru_cache

ZONE_PREFIXES = (
    ("AB", "north"),
    ("EH", "east"),
    ("CF", "central"),
    ("SW", "south"),
)

@lru_cache(maxsize=4096)
def zone_for(postcode: str) -> str:
    normalized = "".join(postcode.split()).upper()
    for prefix, zone in ZONE_PREFIXES:
        if normalized.startswith(prefix):
            return zone
    return "remote"

