def summarize(readings, upper_limit=500):
    totals = {}
    for site, count in readings:
        if site not in totals:
            totals[site] = [0, 0]
        if count < upper_limit:
            totals[site][0] += 1
        else:
            totals[site][1] += 1
    return [
        f"{site}: normal={counts[0]}, out_of_range={counts[1]}"
        for site, counts in sorted(totals.items())
    ]


if __name__ == "__main__":
